draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.angle * Math.PI / 180;
var beta = p.beta;
var g = 9.8;

var pad = 26;
var baseY = H - 34;
var x0 = pad, x1 = W - pad;
var rise = Math.min((x1 - x0) * Math.tan(th), H - 70);
var run = rise / Math.tan(th);
var topX = x1 - run, topY = baseY - rise;

// incline
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6;
ctx.beginPath();
ctx.moveTo(topX, topY); ctx.lineTo(x1, baseY); ctx.lineTo(topX, baseY); ctx.closePath();
ctx.stroke();
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, baseY); ctx.lineTo(W, baseY); ctx.stroke();

// ball sitting on the slope, two thirds of the way up
var f = 0.55;
var bx = x1 + (topX - x1) * f, by = baseY + (topY - baseY) * f;
var R = 22;
var nx = Math.sin(th), ny = -Math.cos(th);     // unit normal (screen coords, y down)
var ccx = bx + nx * R, ccy = by + ny * R;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6;
ctx.beginPath(); ctx.arc(ccx, ccy, R, 0, Math.PI * 2); ctx.stroke();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ccx, ccy); ctx.lineTo(ccx + R * Math.cos(th), ccy - R * Math.sin(th)); ctx.stroke();

function arrow(x, y, dx, dy, col, lab, lx, ly) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + dx, y + dy); ctx.stroke();
  var a = Math.atan2(dy, dx);
  ctx.beginPath();
  ctx.moveTo(x + dx, y + dy);
  ctx.lineTo(x + dx - 7 * Math.cos(a - 0.4), y + dy - 7 * Math.sin(a - 0.4));
  ctx.lineTo(x + dx - 7 * Math.cos(a + 0.4), y + dy - 7 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.fillText(lab, x + dx + lx, y + dy + ly);
}

// weight
arrow(ccx, ccy, 0, 44, C.figure, "Mg", -8, 14);
// normal at the contact
arrow(bx, by, nx * 40, ny * 40, C.figure, "N", 4, -4);
// friction up the slope at the contact
var ux = (topX - x1) / Math.sqrt((topX - x1) * (topX - x1) + (topY - baseY) * (topY - baseY));
var uy = (topY - baseY) / Math.sqrt((topX - x1) * (topX - x1) + (topY - baseY) * (topY - baseY));
arrow(bx, by, ux * 38, uy * 38, C.accent, "f (static)", -46, 14);

// angle mark
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(x1, baseY, 26, Math.PI - th, Math.PI); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText(p.angle.toFixed(0) + " deg", x1 - 58, baseY - 6);

var a = g * Math.sin(th) / (1 + beta);
var fOverMg = beta * Math.sin(th) / (1 + beta);
var muMin = beta * Math.tan(th) / (1 + beta);

ctx.fillStyle = C.ink;
ctx.fillText("a = g sin" + "θ/(1+β) = " + a.toFixed(2) + " m/s²", 8, 16);
ctx.fillStyle = C.figure;
ctx.fillText("f = βMg sinθ/(1+β) = " + fOverMg.toFixed(3) + " Mg", 8, 32);

out.note = "β = " + beta.toFixed(2) + ": a = " + a.toFixed(2) + " m/s², friction needed = " + fOverMg.toFixed(3) + " Mg, minimum μs = " + muMin.toFixed(3);
